function iso(x){ return x.toISOString().replace(/\.\d{3}Z$/,'Z'); }
var anchor = data.ev_start ? new Date(data.ev_start) : new Date();
if (isNaN(anchor.getTime())) { anchor = new Date(); }
var now = new Date();
// 30m of lead so the graph shows what preceded the alarm, not just the breach.
var start = data.in_start || iso(new Date(anchor.getTime() - 30*60000));
var end   = data.in_end   || iso(new Date(Math.min(now.getTime(), anchor.getTime() + 10*60000)));
({
  instance_id: data.in_instance || data.ev_instance || '',
  namespace:   data.ev_ns     || data.in_ns     || 'AWS/EC2',
  metric_name: data.ev_metric || data.in_metric || 'CPUUtilization',
  region:      data.in_region || data.ev_region || 'us-east-1',
  window_start: start, window_end: end,
  window_label: start + ' to ' + end
})

