var src = data.raw;
if (typeof src === 'string') { try { src = JSON.parse(src); } catch (e) { src = {}; } }
var pts = (src && src.Datapoints) || [];
pts.sort(function (a, b) { return new Date(a.Timestamp) - new Date(b.Timestamp); });
var values = [], stamps = [];
pts.forEach(function (p) {
  var v = (p.Average !== undefined && p.Average !== null) ? p.Average : p.Maximum;
  var ms = new Date(p.Timestamp).getTime();
  if (v === undefined || v === null || isNaN(ms)) { return; }
  values.push(v);
  // Epoch SECONDS as a number. The chart renders each label with
  // convertNumberToTimestamp(e * 1000), so an ISO string multiplies to NaN and every
  // tick prints NaN-NaN-aN - the series still draws, so it looks like a formatting
  // quirk rather than the wrong data type.
  stamps.push(Math.floor(ms / 1000));
});
({ results: [ { payload: [ {
  metric: { instance: data.instance, metric: data.name, namespace: data.ns },
  timestamps: stamps, values: values
} ] } ] })
